import type { ReactNode } from "react";
import { StyleSheet, Text, View } from "react-native";
import type { StyleProp, TextStyle, ViewProps, ViewStyle } from "react-native";
import { metrics, useTokens } from "../lib/rn-tokens";

export type BadgeTone = "neutral" | "success" | "info" | "warning" | "danger";
export type BadgeSize = "sm" | "md";

export interface BadgeProps extends Omit<ViewProps, "children"> {
  tone?: BadgeTone;
  size?: BadgeSize;
  icon?: ReactNode;
  children?: ReactNode;
  /** Extend the inner, named parts of the badge: root, icon or label. The React Native counterpart of `classNames`. */
  styles?: {
    root?: StyleProp<ViewStyle>;
    icon?: StyleProp<ViewStyle>;
    label?: StyleProp<TextStyle>;
  };
}

export function Badge({ tone = "neutral", size = "md", icon, children, style, styles: parts, ...props }: BadgeProps) {
  const tokens = useTokens();

  const color = {
    neutral: { text: tokens.textSecondary, background: tokens.surfaceMuted, border: tokens.border },
    success: { text: tokens.success, background: `${tokens.success}1A`, border: `${tokens.success}40` },
    info: { text: tokens.accentStrong, background: tokens.accentSubtle, border: `${tokens.accent}3D` },
    warning: { text: tokens.warning, background: `${tokens.warning}1C`, border: `${tokens.warning}45` },
    danger: { text: tokens.danger, background: `${tokens.danger}1A`, border: `${tokens.danger}42` },
  }[tone];

  const small = size === "sm";

  return (
    <View
      {...props}
      style={[
        local.root,
        {
          minHeight: small ? 22 : 26,
          paddingHorizontal: small ? 8 : 10,
          gap: small ? 4 : 5,
          borderColor: color.border,
          backgroundColor: color.background,
        },
        style,
        parts?.root,
      ]}
    >
      {icon ? <View style={[local.icon, parts?.icon]}>{icon}</View> : null}
      <Text style={[local.label, { color: color.text, fontSize: small ? 11 : metrics.text.xs }, parts?.label]} numberOfLines={1}>
        {children}
      </Text>
    </View>
  );
}

const local = StyleSheet.create({
  root: { alignSelf: "flex-start", flexDirection: "row", alignItems: "center", borderWidth: 1, borderRadius: metrics.radiusPill },
  icon: { alignItems: "center", justifyContent: "center" },
  label: { fontWeight: "500", letterSpacing: -0.12 },
});

export default Badge;

import { useColorScheme } from "react-native";

/** The Manicat UI design tokens as React Native values. Same names and meaning as registry/foundation.css. */
export interface ManicatTokens {
  background: string;
  surface: string;
  surfaceMuted: string;
  foreground: string;
  textSecondary: string;
  textMuted: string;
  border: string;
  borderStrong: string;
  accent: string;
  accentStrong: string;
  accentSubtle: string;
  success: string;
  warning: string;
  danger: string;
  controlOn: string;
  controlTrack: string;
  controlThumb: string;
  controlThumbOn: string;
}

export const lightTokens: ManicatTokens = {
  background: "#ffffff",
  surface: "#ffffff",
  surfaceMuted: "#f6f6f6",
  foreground: "#1b1b1b",
  textSecondary: "#6e6e6e",
  textMuted: "#8f8f8f",
  border: "#ebebeb",
  borderStrong: "#c9c9c9",
  accent: "#4a4a4a",
  accentStrong: "#303030",
  accentSubtle: "rgba(74, 74, 74, 0.1)",
  success: "#1f8a4c",
  warning: "#b8741a",
  danger: "#d03b3b",
  controlOn: "#2c2c2c",
  controlTrack: "#e2e2e2",
  controlThumb: "#ffffff",
  controlThumbOn: "#ffffff",
};

export const darkTokens: ManicatTokens = {
  background: "#2b2b2b",
  surface: "#303030",
  surfaceMuted: "#3c3c3c",
  foreground: "#f1f1f1",
  textSecondary: "#c4c4c4",
  textMuted: "#a0a0a0",
  border: "#454545",
  borderStrong: "#5c5c5c",
  accent: "#cfcfcf",
  accentStrong: "#e6e6e6",
  accentSubtle: "rgba(207, 207, 207, 0.13)",
  success: "#5fd48a",
  warning: "#f0b95c",
  danger: "#ff8a80",
  controlOn: "#ececec",
  controlTrack: "#515151",
  controlThumb: "#f4f4f4",
  controlThumbOn: "#2b2b2b",
};

/** Shape and rhythm shared by every component, in density-independent pixels. */
export const metrics = {
  radiusControl: 18,
  radiusPill: 9999,
  controlHeight: { sm: 36, md: 44, lg: 50 },
  space: { 1: 4, 2: 8, 3: 12, 4: 16, 5: 20 },
  text: { xs: 12, sm: 14, lg: 18 },
} as const;

/** The tokens for the device's current colour scheme. Wrap the app in your own provider if you manage the theme yourself. */
export function useTokens(): ManicatTokens {
  return useColorScheme() === "dark" ? darkTokens : lightTokens;
}
